/* @lc app=leetcode id=3501 lang=kotlin */ class Solution { fun lb(a: List<Int>, v: Int): Int = generateSequence(0 to a.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (a[m] < v) m + 1 to hi else lo to m } }.last().first fun maxActiveSectionsAfterTrade(s: String, queries: Array<IntArray>): List<Int> = s.length.let { n -> s.indices.filter { s[it] == '0' && (it == 0 || s[it - 1] == '1') }.map { st -> st to generateSequence(st) { it + 1 }.takeWhile { it < n && s[it] == '0' }.last() }.let { runs -> runs.map { it.first }.let { starts -> runs.map { it.second }.let { ends -> runs.map { it.second - it.first + 1 }.let { z -> z.zipWithNext { a, b -> a + b }.let { P -> generateSequence(P to 0) { (arr, k) -> (1 shl (k + 1)).takeIf { it <= P.size }?.let { len -> List(P.size - len + 1) { i -> maxOf(arr[i], arr[i + (1 shl k)]) } to k + 1 } }.map { it.first }.toList().let { sp -> s.runningFold(0) { a, c -> a + if (c == '1') 1 else 0 }.let { pre -> queries.map { (l, r) -> lb(ends, l).let { a -> (lb(starts, r + 1) - 1).let { b -> pre[n] + (if (a >= runs.size || b < 0 || a >= b) 0 else (minOf(ends[a], r) - maxOf(starts[a], l) + 1).let { la -> (minOf(ends[b], r) - maxOf(starts[b], l) + 1).let { lb2 -> if (b == a + 1) la + lb2 else maxOf(la + z[a + 1], z[b - 1] + lb2, if (a + 1 <= b - 2) (31 - Integer.numberOfLeadingZeros(b - 2 - a)).let { kk -> maxOf(sp[kk][a + 1], sp[kk][b - 2 - (1 shl kk) + 1]) } else 0) } }) } } } } } } } } } } } }